<template>
  <view class="page">
    <view class="status-spacer" :style="{ height: `${statusBarHeight}px` }" />
    <view class="nav-bar">
      <view class="nav-back" @click="goBack"><image :src="arrowLeftIcon" mode="aspectFit" /></view>
      <text class="nav-title">奖励金</text>
      <view class="nav-placeholder" />
    </view>
    <scroll-view scroll-y class="content" @scrolltolower="loadMoreRecords">
      <view class="balance-card">
        <view class="balance-top"><view><text class="balance-label">奖励金余额(元)</text><text class="balance-value">{{ formatCents(balance) }}</text></view><button class="withdraw-btn" :class="{ disabled: !withdrawEnabled }" @click="openWithdraw">去提现</button></view>
        <view class="balance-tip"><image :src="infoIcon" mode="aspectFit" /><text>{{ withdrawTip }}</text></view>
      </view>
      <view class="section-card">
        <view class="section-title"><image :src="giftIcon" mode="aspectFit" /><text>如何获得奖励金</text></view>
        <view v-if="rulesLoading" class="state-line">加载中...</view><view v-else-if="rulesError" class="state-line state-error" @click="loadRules">加载失败，点击重试</view><view v-else-if="earningMethods.length === 0" class="state-line">暂无可用规则</view>
        <view v-for="rule in earningMethods" v-else :key="rule.code" class="earn-item"><view class="earn-icon" :class="rule.iconClass"><image :src="rule.icon" mode="aspectFit" /></view><view class="earn-info"><text class="earn-name">{{ rule.name }}</text><text class="earn-desc">{{ rule.description }}</text></view><button v-if="rule.actionType === 'NAVIGATE'" class="earn-btn" @click="handleRuleAction(rule)">去看看</button><button v-else-if="rule.actionType === 'SHARE'" class="earn-btn" @click="handleRuleAction(rule)">去分享</button><text v-else class="earn-val">+{{ formatCents(rule.rewardAmount) }}元</text></view>
      </view>
      <view class="detail-tabs"><view v-for="tab in tabs" :key="tab.key" class="detail-tab" :class="{ active: currentTab === tab.key }" @click="switchTab(tab.key)">{{ tab.label }}</view></view>
      <view class="detail-list">
        <view v-if="recordsLoading && records.length === 0" class="state-line">加载中...</view><view v-else-if="recordsError && records.length === 0" class="state-line state-error" @click="loadRecords(true)">加载失败，点击重试</view><view v-else-if="records.length === 0" class="empty-state"><text class="empty-text">暂无相关记录</text></view>
        <view v-else><view v-for="item in normalizedRecords" :key="item.id" class="detail-item"><view class="detail-icon" :style="{ background: item.bg }"><image :src="item.icon" mode="aspectFit" /></view><view class="detail-info"><text class="detail-name">{{ item.title }}</text><text class="detail-time">{{ item.description ? `${item.description} · ` : '' }}{{ item.time }}</text></view><view class="detail-right"><text class="detail-amount" :class="item.amount >= 0 ? 'pos' : 'neg'">{{ item.amount >= 0 ? '+' : '-' }}¥{{ formatCents(Math.abs(item.amount)) }}</text><text class="detail-status">{{ item.status }}</text></view></view><view v-if="recordsLoading" class="state-line">加载中...</view><view v-else-if="hasMore" class="load-more" @click="loadMoreRecords">加载更多</view></view>
      </view>
    </scroll-view>
    <view v-if="withdrawVisible" class="sheet-mask" @click="closeWithdraw"><view class="withdraw-sheet" @click.stop><view class="sheet-title">提现奖励金</view><view class="sheet-row"><text>可提现余额</text><text>¥{{ formatCents(withdrawableBalance) }}</text></view><view class="sheet-row"><text>最低提现金额</text><text>¥{{ formatCents(minimumWithdrawAmount) }}</text></view><input class="amount-input" type="digit" v-model="withdrawAmount" maxlength="12" placeholder="请输入提现金额（元）" @input="sanitizeAmount" /><text v-if="withdrawError" class="withdraw-error">{{ withdrawError }}</text><button class="confirm-btn" :disabled="withdrawSubmitting" @click="submitWithdraw">{{ withdrawSubmitting ? '提交中...' : '确认提现' }}</button></view></view>
  </view>
</template>

<script setup>
import { computed, ref } from "vue";
import { onShow } from "@dcloudio/uni-app";
import { getWorkerRewardOverview, getWorkerRewardRecords, getWorkerRewardRules, withdrawWorkerReward } from "@/api/backend";
import arrowLeftIcon from "/static/icons/worker-reward/arrow-left.svg";
import infoIcon from "/static/icons/worker-reward/circle-info.svg";
import giftIcon from "/static/icons/worker-reward/gift-orange.svg";
import userPlusIcon from "/static/icons/worker-reward/user-plus-orange.svg";
import shareIcon from "/static/icons/worker-reward/share-nodes-blue.svg";
import medalIcon from "/static/icons/worker-reward/medal-green.svg";
import walletIcon from "/static/icons/worker-reward/wallet-blue.svg";

const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 0;
const balance = ref(0), withdrawableBalance = ref(0), minimumWithdrawAmount = ref(0), withdrawEnabled = ref(false), withdrawDisabledReason = ref("");
const rules = ref([]), rulesLoading = ref(false), rulesError = ref(false);
const currentTab = ref("ALL"), tabs = [{ key: "ALL", label: "全部" }, { key: "INCOME", label: "收入" }, { key: "WITHDRAW", label: "提现" }];
const records = ref([]), page = ref(0), size = 20, hasMore = ref(false), recordsLoading = ref(false), recordsError = ref(false);
const withdrawVisible = ref(false), withdrawAmount = ref(""), withdrawError = ref(""), withdrawSubmitting = ref(false), idempotencyKey = ref("");
const earningMethods = computed(() => rules.value.filter((item) => item && item.enabled !== false).map((item) => ({ ...item, icon: item.actionType === "SHARE" ? shareIcon : item.code?.includes("INVITE") ? userPlusIcon : item.code?.includes("WITHDRAW") ? walletIcon : medalIcon, iconClass: item.actionType === "SHARE" ? "share-icon" : item.code?.includes("INVITE") ? "invite-icon" : "medal-icon" })));
const normalizedRecords = computed(() => records.value.map(normalizeRecord));
const withdrawTip = computed(() => withdrawDisabledReason.value || `奖励金满 ${formatCents(minimumWithdrawAmount.value)} 元可提现至微信零钱`);

onShow(loadData);
async function loadData() { await Promise.all([loadOverview(), loadRules()]); await loadRecords(true); }
async function loadOverview() { try { const data = await getWorkerRewardOverview(); balance.value = toCents(data?.balance); withdrawableBalance.value = toCents(data?.withdrawableBalance); minimumWithdrawAmount.value = toCents(data?.minimumWithdrawAmount); withdrawEnabled.value = data?.withdrawEnabled === true; withdrawDisabledReason.value = data?.withdrawDisabledReason || ""; } catch (error) { uni.showToast({ title: error?.message || "奖励金加载失败", icon: "none" }); } }
async function loadRules() { rulesLoading.value = true; rulesError.value = false; try { const data = await getWorkerRewardRules(); rules.value = Array.isArray(data?.earningMethods) ? data.earningMethods : []; if (data?.minimumWithdrawAmount !== undefined && !minimumWithdrawAmount.value) minimumWithdrawAmount.value = toCents(data.minimumWithdrawAmount); } catch (_) { rulesError.value = true; } finally { rulesLoading.value = false; } }
async function loadRecords(reset = false) { if (recordsLoading.value) return; if (reset) { page.value = 0; records.value = []; hasMore.value = false; } recordsLoading.value = true; recordsError.value = false; try { const data = await getWorkerRewardRecords({ page: page.value, size, type: currentTab.value }); const rows = Array.isArray(data?.records) ? data.records : []; records.value = reset ? rows : records.value.concat(rows); hasMore.value = data?.hasMore === true; page.value = Number(data?.page ?? page.value); } catch (error) { recordsError.value = true; if (!records.value.length) uni.showToast({ title: error?.message || "明细加载失败", icon: "none" }); } finally { recordsLoading.value = false; } }
function switchTab(tab) { if (currentTab.value === tab) return; currentTab.value = tab; loadRecords(true); }
function loadMoreRecords() { if (!hasMore.value || recordsLoading.value) return; page.value += 1; loadRecords(false); }
function normalizeRecord(item) { const amount = Number(item?.amount || 0); const income = item?.type === "INCOME" || amount >= 0; return { id: item?.id, title: item?.title || "奖励金变动", description: item?.description || "", amount, time: formatDate(item?.createdAt), status: formatStatus(item?.status, income), icon: income ? (item?.bizType?.includes("INVITE") ? userPlusIcon : giftIcon) : walletIcon, bg: income ? "#FFF3ED" : "#EEF2F7" }; }
function formatStatus(status, income) { if (status === "PENDING") return "处理中"; if (status === "FAILED") return "提现失败"; if (status === "SUCCESS") return income ? "已到账" : "已完成"; return status || ""; }
function formatDate(value) { return value ? String(value).replace("T", " ").slice(0, 16) : "--"; }
function toCents(value) { const number = Number(value); return Number.isFinite(number) ? number : 0; }
function formatCents(value) { return (toCents(value) / 100).toFixed(2); }
function handleRuleAction(rule) { if (rule.actionType === "NAVIGATE" && rule.actionPath) uni.navigateTo({ url: rule.actionPath }); else if (rule.actionType === "SHARE") uni.showToast({ title: "分享功能即将开放", icon: "none" }); }
function openWithdraw() { if (!withdrawEnabled.value) { uni.showToast({ title: withdrawDisabledReason.value || "暂不可提现", icon: "none" }); return; } withdrawVisible.value = true; withdrawError.value = ""; }
function closeWithdraw() { if (!withdrawSubmitting.value) withdrawVisible.value = false; }
function sanitizeAmount(event) { const value = String(event?.detail?.value ?? withdrawAmount.value).replace(/[^0-9.]/g, ""); const firstDot = value.indexOf("."); const normalized = firstDot >= 0 ? `${value.slice(0, firstDot)}.${value.slice(firstDot + 1).replace(/\./g, "").slice(0, 2)}` : value; if (normalized !== withdrawAmount.value) withdrawAmount.value = normalized; idempotencyKey.value = ""; }
function createIdempotencyKey() { const random = globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`; return `worker-reward-withdraw-${Date.now()}-${random}`; }
async function submitWithdraw() { withdrawError.value = ""; const yuan = Number(withdrawAmount.value); if (!withdrawEnabled.value) { withdrawError.value = withdrawDisabledReason.value || "暂不可提现"; return; } if (!withdrawAmount.value || !Number.isFinite(yuan) || yuan <= 0 || !/^\d+(\.\d{1,2})?$/.test(withdrawAmount.value)) { withdrawError.value = "请输入正确的提现金额"; return; } const amount = Math.round(yuan * 100); if (amount < minimumWithdrawAmount.value) { withdrawError.value = `最低提现金额为 ¥${formatCents(minimumWithdrawAmount.value)}`; return; } if (amount > withdrawableBalance.value) { withdrawError.value = "提现金额不能超过可提现余额"; return; } if (!idempotencyKey.value) idempotencyKey.value = createIdempotencyKey(); withdrawSubmitting.value = true; try { await withdrawWorkerReward({ amount, channel: "WECHAT" }, idempotencyKey.value); withdrawVisible.value = false; withdrawAmount.value = ""; idempotencyKey.value = ""; uni.showToast({ title: "提现申请已提交", icon: "success" }); await Promise.all([loadOverview(), loadRecords(true)]); } catch (error) { withdrawError.value = error?.message || "提现失败，请稍后重试"; if (error?.statusCode === 502 || error?.code === 502 || error?.code === "502") await Promise.all([loadOverview(), loadRecords(true)]); } finally { withdrawSubmitting.value = false; } }
function goBack() { uni.navigateBack(); }
</script>

<style scoped>
.page{display:flex;flex-direction:column;height:100vh;overflow:hidden;background:#f7f7f7}.status-spacer,.nav-bar{flex-shrink:0;background:#fff}.nav-bar{position:relative;display:flex;align-items:center;justify-content:space-between;height:100rpx;padding:0 32rpx;box-sizing:border-box}.nav-back,.nav-placeholder{width:64rpx;height:64rpx}.nav-back{display:flex;align-items:center}.nav-back image{width:28rpx;height:32rpx}.nav-title{position:absolute;left:50%;color:#333;font-size:34rpx;font-weight:600;transform:translateX(-50%)}.content{flex:1;min-height:0;padding-top:24rpx;box-sizing:border-box}.balance-card,.section-card,.detail-tabs,.detail-list{margin-right:24rpx;margin-left:24rpx}.balance-card{padding:40rpx 36rpx 30rpx;border-radius:32rpx;color:#fff;background:linear-gradient(135deg,#ff8c5a 0%,#ff6b35 100%);box-shadow:0 12rpx 32rpx rgba(255,107,53,.25)}.balance-top{display:flex;align-items:flex-start;justify-content:space-between}.balance-label{display:block;font-size:26rpx;opacity:.9}.balance-value{display:block;margin-top:12rpx;font-size:72rpx;font-weight:700;line-height:1}.withdraw-btn{height:64rpx;margin:0;padding:0 36rpx;border:0;border-radius:36rpx;background:rgba(255,255,255,.25);color:#fff;font-size:26rpx;font-weight:600;line-height:64rpx}.withdraw-btn.disabled{opacity:.55}.withdraw-btn::after,.earn-btn::after,.confirm-btn::after{border:0}.balance-tip{display:flex;align-items:center;gap:10rpx;margin-top:24rpx;font-size:24rpx;opacity:.88}.balance-tip image{width:24rpx;height:24rpx}.section-card{margin-top:24rpx;padding:32rpx;border-radius:24rpx;background:#fff}.section-title{display:flex;align-items:center;gap:12rpx;margin-bottom:16rpx;color:#333;font-size:30rpx;font-weight:600}.section-title image{width:30rpx;height:30rpx}.earn-item{display:flex;align-items:center;gap:20rpx;padding:20rpx 0;border-bottom:1rpx solid #f5f5f5}.earn-item:last-child{border-bottom:0}.earn-icon{display:flex;align-items:center;justify-content:center;width:80rpx;height:80rpx;flex-shrink:0;border-radius:20rpx}.invite-icon{background:#fff3ed}.share-icon{background:#eff6ff}.medal-icon{background:#ecfdf5}.earn-icon image{width:34rpx;height:34rpx}.earn-info{flex:1;min-width:0}.earn-name,.earn-desc{display:block}.earn-name{color:#333;font-size:28rpx;font-weight:500}.earn-desc{margin-top:4rpx;color:#999;font-size:23rpx}.earn-val{flex-shrink:0;color:#ff6b35;font-size:25rpx;font-weight:600}.earn-btn{height:56rpx;margin:0;padding:0 28rpx;border:0;border-radius:28rpx;background:#fff3ed;color:#ff6b35;font-size:24rpx;font-weight:600;line-height:56rpx}.detail-tabs{display:flex;margin-top:24rpx;border-radius:24rpx 24rpx 0 0;background:#fff}.detail-tab{position:relative;flex:1;padding:26rpx 0;color:#666;font-size:28rpx;text-align:center}.detail-tab.active{color:#ff6b35;font-weight:600}.detail-tab.active::after{position:absolute;right:50%;bottom:0;width:48rpx;height:6rpx;border-radius:4rpx;background:#ff6b35;content:"";transform:translateX(50%)}.detail-list{margin-bottom:24rpx;padding:8rpx 32rpx 16rpx;border-radius:0 0 24rpx 24rpx;background:#fff}.detail-item{display:flex;align-items:center;gap:20rpx;padding:24rpx 0;border-bottom:1rpx solid #f5f5f5}.detail-item:last-child{border-bottom:0}.detail-icon{display:flex;align-items:center;justify-content:center;width:76rpx;height:76rpx;flex-shrink:0;border-radius:50%}.detail-icon image{width:32rpx;height:32rpx}.detail-info{flex:1;min-width:0}.detail-name,.detail-time,.detail-status{display:block}.detail-name{color:#333;font-size:28rpx;font-weight:500}.detail-time{margin-top:6rpx;color:#999;font-size:22rpx}.detail-right{flex-shrink:0;text-align:right}.detail-amount{display:block;font-size:30rpx;font-weight:700}.detail-amount.pos{color:#ff6b35}.detail-amount.neg{color:#999}.detail-status{margin-top:6rpx;color:#34c77b;font-size:20rpx}.state-line,.load-more{padding:32rpx 20rpx;color:#999;font-size:25rpx;text-align:center}.state-error{color:#ff6b35}.load-more{color:#666}.empty-state{padding:80rpx 20rpx;text-align:center}.empty-text{color:#999;font-size:26rpx}.sheet-mask{position:fixed;z-index:10;inset:0;display:flex;align-items:flex-end;background:rgba(0,0,0,.45)}.withdraw-sheet{width:100%;padding:36rpx 32rpx calc(32rpx + env(safe-area-inset-bottom));border-radius:28rpx 28rpx 0 0;background:#fff;box-sizing:border-box}.sheet-title{margin-bottom:28rpx;color:#333;font-size:34rpx;font-weight:600;text-align:center}.sheet-row{display:flex;justify-content:space-between;margin-bottom:18rpx;color:#666;font-size:26rpx}.sheet-row text:last-child{color:#333;font-weight:600}.amount-input{height:88rpx;margin:24rpx 0 12rpx;padding:0 24rpx;border:1rpx solid #eee;border-radius:14rpx;font-size:30rpx;box-sizing:border-box}.withdraw-error{display:block;min-height:36rpx;color:#e64340;font-size:24rpx}.confirm-btn{height:84rpx;margin:20rpx 0 0;border:0;border-radius:42rpx;background:#ff6b35;color:#fff;font-size:30rpx;line-height:84rpx}.confirm-btn[disabled]{opacity:.6}
</style>
